import base64, hashlib, json, lzma
from pathlib import Path
_d = Path("rjy_resume")
_d.mkdir(exist_ok=True)
(_d / f"part{PART}.txt").write_text(DATA)
_parts = [_d / f"part{k}.txt" for k in range(1, N_PARTS + 1)]
if all(p.exists() for p in _parts):
    _b = "".join(p.read_text() for p in _parts)
    if hashlib.sha256(_b.encode()).hexdigest() != SHA256:
        raise SystemExit("resume data damaged (sha256 mismatch): paste the data cells again")
    _payload = json.loads(lzma.decompress(base64.b85decode(_b)))
    for _path, _rows in _payload["files"].items():
        _p = Path(_path)
        _p.parent.mkdir(parents=True, exist_ok=True)
        with open(_p, "w", encoding="utf-8") as _f:
            for _r in _rows:
                _f.write(json.dumps(_r, ensure_ascii=False) + "\n")
        print(f"restored {_path} ({len(_rows)} rows)")
    print("resume data complete and verified")
else:
    print(f"resume data part {PART}/{N_PARTS} saved; waiting for the other parts")
